package com.ngocdevv.nativecook.blocks.charts.growthodometertimeline

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

// Embedded unchanged PNGs keep the copyable block self-contained without a Gradle resource rule.
internal object GrowthAssets {
    val digits: Bitmap by lazy {
        val bytes = Base64.decode(
            listOf(
                "",
            ).joinToString(""), Base64.DEFAULT,
        )
        requireNotNull(BitmapFactory.decodeByteArray(bytes, 0, bytes.size, BitmapFactory.Options().apply {
            inScaled = false
            inPreferredConfig = Bitmap.Config.ARGB_8888
        }))
    }
